// OpenCode plugin generated by `ai-learn init` / `ai-learn update`.
//
// OpenCode has no hook file: it loads plugins from .opencode/plugins/ and exposes
// `tool.execute.before`, where a `throw` refuses the call. This plugin does one
// thing — translate an OpenCode tool call into the PreToolUse payload
// `ai-learn guard` already understands, run `decide`, and throw on its denial.
// `decide` stays the single part under test; nothing is re-implemented here.
//
// Same contract as the Claude hook: the locally-resolved binary is used first
// (no process per write when the module loads in-process), and anything that is
// not an explicit deny is fail-open but never silent — "NOT checked" goes to
// stderr and to .ai-learn/guard-unchecked.jsonl.

import { spawnSync } from "node:child_process";
import { appendFileSync, existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, isAbsolute, resolve } from "node:path";

const BINARY = __BINARY__;
const LOG_MAX_BYTES = 256 * 1024;

// Paths arrive with Windows separators from Windows tool calls and with spaces
// from any platform; the guard normalizes the rest, but a backslash on POSIX
// would be read as part of the file name and silently miss `src/**`.
function portable(value) {
  return typeof value === "string" ? value.replace(/\\/g, "/") : value;
}

// OpenCode resolves a tool's relative path against the directory the session was
// started in, not against the project root. `decide` resolves relative paths
// against the root it is handed, so a session started in `<root>/src` would
// otherwise judge `<root>/a.js` while the real target is `<root>/src/a.js`.
function absolutePath(value, start) {
  const normalized = portable(value);

  if (!normalized) {
    return normalized;
  }

  return isAbsolute(normalized) ? normalized : resolve(start, normalized);
}

// `apply_patch` is how GPT-family models edit in OpenCode: one patchText, many
// files. Each file section becomes one Write-shaped payload — the destination
// of `Add`/`Update`, `Move to`, or a `Delete` — so a patch can never touch a
// path the guard would refuse to a Write. The added lines ride along as
// `content`, like a Write payload; `decide` judges the path.
function patchPayloads(patchText, start) {
  const out = [];
  let current = null;
  let malformed = false;

  // CRLF too: a header line would otherwise keep its trailing `\r` and match nothing.
  // `\s*` after the colon: OpenCode's own parser accepts `*** Add File:src/a.js`
  // and tab-separated headers, and a header we fail to read is a write we would
  // otherwise allow without judging.
  for (const raw of String(patchText || "").split(/\r?\n/)) {
    // Leading whitespace is tolerated: an indented header is still a header.
    const line = raw.trimStart();
    const file = line.match(/^\*\*\* (Add|Update|Delete) File:\s*(.+)$/);
    const move = line.match(/^\*\*\* Move to:\s*(.+)$/);
    const headerish = /^\*\*\* (?:Add|Update|Delete) File:|^\*\*\* Move to:/.test(line);

    if (file) {
      const payload = { tool_name: "Write", tool_input: { file_path: absolutePath(file[2].trim(), start) } };
      out.push(payload);
      // A deleted file has no added lines to collect.
      current = file[1] === "Delete" ? null : payload;
    } else if (move) {
      out.push({ tool_name: "Write", tool_input: { file_path: absolutePath(move[1].trim(), start) } });
      current = null;
    } else if (headerish) {
      malformed = true;
      current = null;
    } else if (/^\*\*\* /.test(line)) {
      current = null;
    } else if (current && line.startsWith("+")) {
      current.tool_input.content = `${current.tool_input.content || ""}${line.slice(1)}\n`;
    }
  }

  return { payloads: out, malformed };
}

// Read-only tools never touch a file: they stay out, so a read spawns no process
// and can never be refused. Anything else with a path is passed under its own
// name — the guard reports a tool it does not know as not a write tool.
const READ_ONLY_TOOLS =
  /^(read|glob|grep|list|ls|webfetch|websearch|todowrite|todoread|skill|task|question|lsp|codesearch)$/i;

// Only used when the shell directory itself contains whitespace, which the
// guard's tokenizer cannot express. Conservative on purpose: a false positive
// journals an unchecked write, a false negative would hide one.
function looksLikeRelativeWrite(command) {
  return (
    /(^|[^>])>{1,2}\s*["']?(?![\/~$])[^\s"'<>|;&]+/.test(command) ||
    /\b(?:tee|cp|mv|ln|install)\b/.test(command) ||
    /\bsed\b[^|;&\n]*\s-i\b/.test(command)
  );
}

function toPayloads(tool, args, start) {
  const a = args || {};

  if (tool === "write") {
    return [
      {
        tool_name: "Write",
        tool_input: { file_path: absolutePath(a.filePath || a.file_path || a.path, start), content: a.content },
      },
    ];
  }
  if (tool === "edit") {
    return [
      {
        tool_name: "Edit",
        tool_input: { file_path: absolutePath(a.filePath || a.file_path || a.path, start), new_string: a.newString || a.new_string },
      },
    ];
  }
  if (tool === "bash" || tool === "shell") {
    // The shell runs in the session directory, or in `workdir` when given, so a
    // relative write target means that directory — not the project root. The
    // guard's shell parser resolves targets against the `cd` in the command, so
    // the directory rides in as that `cd`: the judged target is then the one the
    // shell would really write. Without it, a session opened in `<root>/src`
    // would judge `<root>/a.js` for `printf x > a.js`.
    const base = a.workdir ? absolutePath(a.workdir, start) : start;
    const command = typeof a.command === "string" ? a.command : null;

    // The parser splits on whitespace: a `cd` it cannot express would make it
    // judge the wrong directory. Leave the command untouched there (git/mode
    // checks still apply), but a relative-looking write is then unjudged — say
    // so, instead of letting the fallback be silent.
    const spaced = /\s/.test(base);
    const judged = command && !spaced ? `cd ${portable(base)} && ${command}` : command;
    const unchecked =
      command && spaced && looksLikeRelativeWrite(command)
        ? `the shell runs in ${base}, whose path the guard's parser cannot express; relative writes were NOT judged`
        : undefined;

    return [{ tool_name: "Bash", tool_input: { command: judged }, cwd: start, unchecked }];
  }
  if (tool === "apply_patch" || tool === "patch") {
    const { payloads, malformed } = patchPayloads(a.patchText || a.patch_text, start);

    // A patch we could not read a single file out of is not "nothing to check":
    // it is an unchecked write, reported as such instead of silently allowed.
    if (!payloads.length) {
      return [
        {
          tool_name: "Write",
          tool_input: {},
          unchecked: malformed
            ? "apply_patch had a malformed file header"
            : "apply_patch had no readable file section",
        },
      ];
    }

    // A readable section next to a broken one would otherwise judge half the
    // patch and silently drop the other half.
    if (malformed) {
      payloads.push({
        tool_name: "Write",
        tool_input: {},
        unchecked: "apply_patch had a malformed file header",
      });
    }

    return payloads;
  }
  if (READ_ONLY_TOOLS.test(tool || "")) {
    return [];
  }
  const unknownPath = a.file_path || a.filePath || a.path || a.notebook_path;

  if (!unknownPath) {
    return [];
  }

  // Forwarded under its own name (the guard does not judge it), but never in
  // silence: an MCP `write_file` is a write like any other.
  return [
    {
      tool_name: tool,
      tool_input: { ...a, file_path: absolutePath(unknownPath, start) },
      unchecked: `tool ${tool} is not mapped; the guard did not judge it`,
    },
  ];
}

// In-process first: OpenCode runs on Bun, which loads the guard's CommonJS
// directly — no `node` required on OpenCode's PATH, and no process per write.
// The spawn is the fallback for a package no longer at BINARY.
let local = null;

try {
  if (BINARY && existsSync(BINARY)) {
    local = createRequire(BINARY)("./lib/guard.js");
  }
} catch {
  local = null;
}

// The root is the OUTERMOST `.ai-learn/guard.json` above the start directory —
// the same rule as `findProjectRoot`, reused from the guard module whenever it
// loaded. The walk is only the no-module fallback, for the journal entry.
function projectRoot(directory) {
  if (local && typeof local.findProjectRoot === "function") {
    try {
      return local.findProjectRoot(directory);
    } catch {}
  }

  const start = resolve(directory || process.cwd());
  let dir = start;
  let found = null;

  for (;;) {
    try {
      if (existsSync(`${dir}/.ai-learn/guard.json`)) {
        found = dir;
      }
    } catch {
      return found || start;
    }
    const parent = dirname(dir);
    if (parent === dir) {
      return found || start;
    }
    dir = parent;
  }
}

// "NOT checked" has to be visible: on stderr now, and in the project's journal
// (the learner and the maintainer read it). Never throws.
function noteUnchecked(hook, reason) {
  process.stderr.write(`ai-learn guard: ${reason}; this write was NOT checked\n`);

  try {
    const root = projectRoot(hook.cwd);

    if (local && typeof local.recordUnchecked === "function") {
      local.recordUnchecked({ root, hook, result: { reason } });
      return;
    }
    if (!existsSync(`${root}/.ai-learn`)) {
      return;
    }

    const log = `${root}/.ai-learn/guard-unchecked.jsonl`;

    // Bounded like the guard's own denial log: a broken guard must not grow it forever.
    if (existsSync(log) && statSync(log).size > LOG_MAX_BYTES) {
      const kept = readFileSync(log, "utf8").split("\n").filter(Boolean).slice(-200);
      writeFileSync(log, kept.length ? `${kept.join("\n")}\n` : "");
    }
    appendFileSync(
      log,
      `${JSON.stringify({
        at: new Date().toISOString(),
        tool: hook.tool_name || null,
        path: (hook.tool_input && (hook.tool_input.file_path || hook.tool_input.path)) || null,
        reason,
      })}\n`,
    );
  } catch {
    // a missing journal is never worth failing a write over
  }
}

function spawnGuard(hook) {
  const res = spawnSync("node", [BINARY, "guard"], {
    input: JSON.stringify(hook),
    encoding: "utf8",
    timeout: 60000,
  });

  if (res.error) {
    return { decision: "unchecked", reason: `could not run (${res.error.code || res.error.message})` };
  }
  if (res.status === 2) {
    const reason = (res.stderr || "").replace(/^ai-learn guard: /, "").trim();
    return { decision: "deny", reason: reason || "refused by ai-learn guard" };
  }
  if (res.status === 0) {
    // `guardCommand` fail-opens on an internal error too, but says so on stderr
    // and journals it — forward that, so the fail-open is never silent here.
    if (/this write was NOT checked/.test(res.stderr || "")) {
      process.stderr.write(res.stderr);
    }
    return { decision: "allow", reason: "allowed" };
  }
  return { decision: "unchecked", reason: `the guard gave no decision (exit ${res.status})` };
}

// A guard that cannot decide is fail-open, but it says so — it never silently
// allows a write it never judged.
function evaluate(hook) {
  if (local && typeof local.decide === "function") {
    const root = projectRoot(hook.cwd);

    try {
      const result = local.decide(hook, root);

      // Same visibility as the Claude hook: a denial is logged where `check`
      // reads it, not only thrown back at the model.
      if (result && result.decision === "deny" && typeof local.recordDenial === "function") {
        try {
          local.recordDenial({ root, hook, result });
        } catch {}
      }

      return result;
    } catch {
      return { decision: "unchecked", reason: "the guard errored" };
    }
  }
  if (!BINARY || !existsSync(BINARY)) {
    return { decision: "unchecked", reason: "no guard module to run" };
  }

  return spawnGuard(hook);
}

// OpenCode 1.x loads `default.server`; the same function is the `server` of the
// 2.x shape below. Exported once, never twice: two registrations would double
// every denial.
const AiLearnGuard = async ({ directory } = {}) => {
  const start = resolve(directory || process.cwd());

  return {
    "tool.execute.before": async (input, output) => {
      for (const payload of toPayloads(input.tool, output.args, start)) {
        const hook = { tool_name: payload.tool_name, tool_input: payload.tool_input, cwd: payload.cwd || start };
        const result = evaluate(hook);

        if (result && result.decision === "deny") {
          throw new Error(`ai-learn guard: ${result.reason}`);
        }

        // A payload the guard could not fully judge (a malformed patch section,
        // an unmapped tool, a spaced shell directory) is fail-open, but traced.
        if (payload.unchecked) {
          noteUnchecked(hook, payload.unchecked);
        } else if (result && result.decision === "unchecked") {
          noteUnchecked(hook, result.reason);
        }
      }
    },
  };
};

// OpenCode 2.x loads a default export `{ id, server, setup }`; `setup` registers
// the same check on its own hook. 1.x also calls `setup`, with a partial context
// and no `ctx.tool`: return early, or 1.x fails the whole plugin.
async function setup(ctx) {
  if (!ctx || !ctx.tool || typeof ctx.tool.hook !== "function") {
    return;
  }
  const directory = (ctx.location && ctx.location.directory) || process.cwd();
  const hooks = await AiLearnGuard({ directory });

  await ctx.tool.hook("execute.before", (event) =>
    hooks["tool.execute.before"]({ tool: event.tool }, { args: event.input }),
  );
}

export default { id: "ai-learn.guard", server: AiLearnGuard, setup };
